78,3.78,0,1,1-3.778-3.78A3.779,3.779,0,0,1,19.317,70.408Z"></path><path d="M19.317,56.549a3.78,3.78,0,1,1-3.778-3.78A3.776,3.776,0,0,1,19.317,56.549Z"></path><path d="M19.317,42.687a3.78,3.78,0,1,1-3.778-3.78A3.779,3.779,0,0,1,19.317,42.687Z"></path><path d="M19.317,28.828a3.78,3.78,0,1,1-3.778-3.78A3.779,3.779,0,0,1,19.317,28.828Z"></path><path d="M52.272,84.265a3.78,3.78,0,1,1-3.779-3.78A3.777,3.777,0,0,1,52.272,84.265Z"></path><path d="M52.272,70.408a3.78,3.78,0,1,1-3.779-3.78A3.78,3.78,0,0,1,52.272,70.408Z"></path><path d="M52.272,56.549a3.78,3.78,0,1,1-3.779-3.78A3.777,3.777,0,0,1,52.272,56.549Z"></path><path d="M52.272,42.687a3.78,3.78,0,1,1-3.779-3.78A3.78,3.78,0,0,1,52.272,42.687Z"></path><path d="M85.229,84.265a3.78,3.78,0,1,1-3.778-3.78A3.777,3.777,0,0,1,85.229,84.265Z"></path><path d="M85.229,70.408a3.78,3.78,0,1,1-3.778-3.78A3.779,3.779,0,0,1,85.229,70.408Z"></path><path d="M85.229,56.549a3.78,3.78,0,1,1-3.778-3.78A3.776,3.776,0,0,1,85.229,56.549Z"></path><path d="M118.187,84.265a3.78,3.78,0,1,1-3.778-3.78A3.777,3.777,0,0,1,118.187,84.265Z"></path><path d="M118.187,70.408a3.78,3.78,0,1,1-3.778-3.78A3.78,3.78,0,0,1,118.187,70.408Z"></path><path d="M151.141,84.265a3.78,3.78,0,1,1-3.778-3.78A3.777,3.777,0,0,1,151.141,84.265Z"></path></g></svg><div role="region" aria-label="Long description for dot plot" class="sr-only"><ul>
<li>The data for the dot plot are as follows:<br>
<ul>
<li>22: 5 dots</li>
<li>23: 4 dots</li>
<li>24: 3 dots</li>
<li>25: 2 dots</li>
<li>26: 1 dot</li>
</ul>
</li>
</ul></div></figure></p>
<p style="text-align: left;">Data set A has <math alttext="15"><mn>15</mn>
</math> values and is represented by the dot plot shown. Data set B is created by adding <math alttext="46"><mn>46</mn>
</math> to each of the values in data set A. Which of the following correctly compares the medians and the ranges of data sets A and B?</p>$SATQ$, $SATQ$[{"id":"566cc376-987d-4163-b8aa-0e764c174eea","content":"<p style=\"text-align: left;\">The median of data set B is greater than the median of data set A, and the range of data set B is equal to the range of data set A.</p>"},{"id":"b010a4c6-b95f-4a10-b42d-d6e9ac7d1ead","content":"<p style=\"text-align: left;\">The median of data set B is greater than the median of data set A, and the range of data set B is greater than the range of data set A.</p>"},{"id":"99c0ba6a-0d4c-4ad3-85f7-10728fb08de3","content":"<p style=\"text-align: left;\">The median of data set B is equal to the median of data set A, and the range of data set B is greater than the range of data set A.</p>"},{"id":"332e9274-8c60-4c1d-bae4-890f5517d960","content":"<p style=\"text-align: left;\">The median of data set B is equal to the median of data set A, and the range of data set B is equal to the range of data set A.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["566cc376-987d-4163-b8aa-0e764c174eea"]$SATQ$::jsonb, $SATQ$<p style="text-align: left;">Choice A is correct. The median is the middle value in a data set when the data are arranged in order from least to greatest. Since there are <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="15"><mn>15</mn></math> values in data set A, the median is the <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="8th"><mn>8</mn><mtext>th</mtext></math> value. The <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="8th"><mn>8</mn><mtext>th</mtext></math> value is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="23"><mn>23</mn></math>, so&nbsp;the median of data set A is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="23"><mn>23</mn></math>. The range is found by subtracting the minimum value in a data set from the maximum value. The minimum value in data set A is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="22"><mn>22</mn></math> and the maximum value is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="26"><mn>26</mn></math>. Therefore, the range of data set A is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="26 minus 22"><mn>26</mn><mo>-</mo><mn>22</mn></math>, or <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="4"><mn>4</mn></math>. It’s given that data set B is created by adding <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="46"><mn>46</mn></math> to each of the values in data set A. Therefore, the <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="8th"><mn>8</mn><mtext>th</mtext></math> value in data set B is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="23 plus 46"><mn>23</mn><mo>+</mo><mn>46</mn></math>, or <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="69"><mn>69</mn></math>, so the median of data set B is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="69"><mn>69</mn></math>. The minimum value in data set B is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="22 plus 46"><mn>22</mn><mo>+</mo><mn>46</mn></math>, or <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="68"><mn>68</mn></math>, and the maximum&nbsp;value is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="26 plus 46"><mn>26</mn><mo>+</mo><mn>46</mn></math>, or <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="72"><mn>72</mn></math>. Therefore, the range of data set B is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="72 minus 68"><mn>72</mn><mo>-</mo><mn>68</mn></math>, or <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="4"><mn>4</mn></math>. Since the median of data set A is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="23"><mn>23</mn></math>, and the median of data set B is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="69"><mn>69</mn></math>, the median of data set B is greater than the median of data set A. Since the ranges of data sets A and B are both <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="4"><mn>4</mn></math>, the range of data set B is equal to the range of data set A.</p>
<p style="text-align: left;">Choice B is incorrect and may result from conceptual or calculation errors.</p>
<p style="text-align: left;">Choice C is incorrect and may result from conceptual or calculation errors.</p>
